import { sfx } from '../core/sfx';

// Skip's sound set, ported from the prototype and generated by the shared synth.

const SCALE = [523.25, 587.33, 659.25, 783.99, 880, 1046.5, 1174.66, 1318.51, 1567.98, 1760, 2093];
/** Pitch climbs with the Perfect streak and holds at the top note instead of wrapping. */
const note = (streak: number) => SCALE[Math.min(Math.max(0, streak), SCALE.length - 1)];

export const audio = {
  plip(streak: number, vol = 0.3) {
    const f = note(streak);
    sfx.tone(f, 0.13, { vol, slideTo: f * 1.45 });
    sfx.noise(0.07, 0.05, 2600, 1.2);
  },
  /** A flat, duller plip for an untimed skip. */
  plipMiss() {
    sfx.tone(392, 0.11, { type: 'triangle', vol: 0.16, slideTo: 370 });
    sfx.noise(0.06, 0.04, 1300, 1.2);
  },
  perfect(streak: number) {
    audio.plip(streak);
    const f = note(streak);
    sfx.tone(f * 2, 0.12, { type: 'triangle', vol: 0.05, delay: 0.04 });
    sfx.tone(440, 0.2, { vol: 0.16, slideTo: 990 });
    sfx.noise(0.1, 0.05, 2000, 1.2);
  },
  good(streak: number) {
    audio.plip(streak, 0.24);
    sfx.tone(440, 0.16, { vol: 0.1, slideTo: 800 });
  },
  queued() { sfx.tone(700, 0.05, { type: 'triangle', vol: 0.06 }); },
  early() {
    sfx.tone(210, 0.14, { vol: 0.14, slideTo: 170 });
    sfx.noise(0.06, 0.03, 600, 1);
  },
  thunk() { sfx.tone(120, 0.18, { type: 'triangle', vol: 0.45, slideTo: 70 }); sfx.noise(0.1, 0.15, 500, 1.2); },
  boing() { sfx.tone(260, 0.32, { vol: 0.3, slideTo: 900 }); sfx.tone(520, 0.2, { type: 'triangle', vol: 0.06, slideTo: 1400, delay: 0.03 }); },
  quack() { sfx.tone(460, 0.1, { type: 'sawtooth', vol: 0.09, slideTo: 300 }); sfx.tone(430, 0.12, { type: 'sawtooth', vol: 0.08, slideTo: 280, delay: 0.12 }); },
  glass() { sfx.tone(1900 + Math.random() * 300, 0.09, { type: 'triangle', vol: 0.09 }); sfx.tone(2800, 0.12, { vol: 0.04, delay: 0.03 }); },
  throw() { sfx.noise(0.25, 0.1, 900, 0.6); },
  sink() { sfx.tone(300, 0.4, { vol: 0.2, slideTo: 120 }); sfx.noise(0.45, 0.12, 400, 0.7); },
  plunk() { sfx.tone(160, 0.35, { vol: 0.35, slideTo: 70 }); sfx.noise(0.4, 0.2, 500, 0.7); },
  /** Flying through a glass hoop: a bright upward sweep. */
  hoop() {
    [1046.5, 1318.51, 1567.98, 2093].forEach((f, i) => sfx.tone(f, 0.12, { type: 'triangle', vol: 0.08, delay: i * 0.045 }));
    sfx.noise(0.18, 0.04, 5000, 0.8);
  },
  /** Distance milestone: a little C major fanfare. */
  milestone(big: boolean) {
    const notes = big ? [523.25, 659.25, 783.99, 1046.5, 1318.51] : [783.99, 1046.5, 1318.51];
    notes.forEach((f, i) => sfx.tone(f, 0.16, { type: 'triangle', vol: 0.12, delay: i * 0.08 }));
  },
  fever() {
    [523.25, 783.99, 1046.5, 1567.98].forEach((f, i) => sfx.tone(f, 0.22, { type: 'square', vol: 0.05, delay: i * 0.06, slideTo: f * 1.02 }));
    sfx.noise(0.35, 0.06, 3000, 0.6);
  },
  /** Tutorial cue while the game is in slow motion. */
  tick() { sfx.tone(1318.51, 0.05, { type: 'triangle', vol: 0.05 }); },
  click() { sfx.tone(620, 0.05, { type: 'triangle', vol: 0.05 }); },
};
